<script setup lang="ts">
import {ref} from 'vue';import {api} from '../api';
const sent=ref(false),busy=ref(false),error=ref('');const name=ref(''),company=ref(''),email=ref(''),details=ref(''),consent=ref(false);
async function submit(){if(busy.value)return;busy.value=true;error.value='';try{await api('/leads','POST',{name:name.value.trim(),company:company.value.trim(),email:email.value.trim(),details:details.value.trim(),consent:consent.value});sent.value=true}catch(e){error.value=e instanceof Error?e.message:'提交失败，请稍后再试'}finally{busy.value=false}}
</script>
<template><div class="container page"><div class="subhero"><span class="eyebrow">CONTACT</span><h1>让团队更快交付<em>真正可运行的应用</em></h1><p>企业私有化、OEM、FDE团队和设计器接入方案欢迎咨询。</p></div><div class="contact-layout"><div class="tile"><h2>预约产品演示</h2><p>填写信息后，我们将通过你填写的工作邮箱联系你。</p><div v-if="sent" class="success" role="status">咨询已提交。感谢你的联系。</div><form v-else class="form" @submit.prevent="submit"><label>姓名<input required maxlength="120" v-model="name" autocomplete="name"/></label><label>企业名称<input required maxlength="200" v-model="company" autocomplete="organization"/></label><label>工作邮箱<input type="email" required maxlength="320" v-model="email" autocomplete="email"/></label><label>希望了解的内容<textarea required maxlength="4000" v-model="details" rows="5" placeholder="如：FDE交付、数据连接、OEM授权..."/></label><label class="consent"><input type="checkbox" required v-model="consent"/> 我同意根据 <router-link to="/privacy">隐私政策</router-link> 处理本次咨询所需的联系信息。</label><p v-if="error" class="error" role="alert">{{error}}</p><button :disabled="busy" type="submit">{{busy?'正在提交...':'提交企业咨询 →'}}</button></form></div><aside class="tile"><h2>合作方向</h2><p>▸ 企业软件与 AI 原生组织</p><p>▸ FDE / 快速项目交付</p><p>▸ 私有化部署与 OEM 授权</p><p>▸ 独立 AI Designer 对接</p><p class="muted">请勿通过咨询表单提交密码、密钥或敏感业务数据。</p></aside></div></div></template>
